const containerVariants = cva("mx-auto", {
  variants: {
    size: {
      sm: "max-w-screen-sm",
      md: "max-w-screen-md", 
      lg: "max-w-screen-lg",
      xl: "max-w-screen-xl",
      "2xl": "max-w-screen-2xl",
      full: "max-w-full",
      constrained: "max-w-7xl",
      prose: "max-w-prose",
      "3xl": "max-w-[1600px]",
      "4xl": "max-w-[1920px]",
